// Prepended to each worker setup body by scripts/build-advanced-plugins.mjs.
// No runtime imports or external dependencies. Each JSON is self-contained.
const h = ctx.h;
const text = value => String(value == null ? '' : value);
const tagsOf = card => Array.isArray(card.tags) ? card.tags : [];
const includes = (value, query) => text(value).toLowerCase().includes(text(query).toLowerCase());
const number = (value, fallback, min, max) => Number.isFinite(Number(value))
  ? Math.max(min, Math.min(max, Number(value))) : fallback;
let panel = null;
let queue = Promise.resolve();
let notice = '';
let draw = async () => [];
let heading = '';
let refreshButton;
const action = fn => (...args) => {
  queue = queue.then(() => fn(...args)).catch(async error => {
    notice = text(error.message || error);
    await ctx.api.ui.showToast(notice, 'error');
  });
  return queue;
};
const button = (label, fn, disabled = false) => h('button', {
  type: 'button', className: 'btn', disabled, onclick: action(fn)
}, label);
const field = (label, value, change, type = 'text') => h('label', { className: 'lab-field' }, [
  h('span', {}, label), h(type === 'textarea' ? 'textarea' : 'input', {
    type: type === 'textarea' ? undefined : type, value,
    'aria-label': label, oninput: event => { change(event.target.value); }
  }, type === 'textarea' ? value : undefined)
]);
const select = (label, value, choices, change) => h('label', { className: 'lab-field' }, [
  h('span', {}, label), h('select', { 'aria-label': label, onchange: event => { change(event.target.value); } },
    choices.map(([id, name]) => h('option', { value: id, selected: id === value }, name)))
]);
const box = children => h('div', { className: 'lab-box' }, children);
const row = children => h('div', { className: 'lab-row' }, children);
const title = card => card.title || '(Untitled)';
async function paint() {
  if (!panel) return;
  const children = await draw();
  await panel.update(h('section', { className: 'cs-lab', id: ctx.modId + '-panel', 'aria-label': heading }, [
    row([h('h2', {}, heading), button('Refresh', async () => { notice = ''; await paint(); }),
      button('Close', async () => { await panel.remove(); panel = null; })]),
    h('p', { role: 'status', className: 'lab-notice' }, notice), ...children
  ]));
}
async function start(label, render) {
  heading = label;
  draw = render;
  refreshButton = await ctx.api.ui.inject('.header', button(label, async () => {
    if (!panel) panel = await ctx.api.ui.inject('#main', h('section', {}), 'before');
    await paint();
  }), 'append');
  // Notify without replacing a form while someone is typing. Refresh is explicit.
  ctx.api.data.onUpdate(() => { notice = 'Cards changed. Refresh to see the latest data.'; });
}
async function readState(key, fallback) {
  const stored = await ctx.api.storage.get(key);
  return stored && stored.schema === 1 ? stored.value : fallback;
}
const writeState = (key, value) => ctx.api.storage.set(key, { schema: 1, value });
const cardSignature = card => JSON.stringify([card.title, card.body, tagsOf(card), card.parentId]);

let front = '', back = '', revealed = false;
let activeId = null;
const meta = card => card.modsData && card.modsData[ctx.modId] || {};
async function grade(id, good) {
  const card = await ctx.api.data.getCard(id);
  if (!card) throw new Error('Study card no longer exists.');
  const state = meta(card);
  // Re-check due time to make rapid duplicate rating clicks idempotent.
  if ((state.due || 0) > Date.now()) return;
  const interval = good ? Math.min(365, Math.max(1, (state.interval || 0) * 2)) : 0;
  const next = { schema: 1, interval, due: Date.now() + (good ? interval * 86400000 : 60000),
    reviews: (state.reviews || 0) + 1, lapses: (state.lapses || 0) + (good ? 0 : 1) };
  await ctx.api.data.updateCard(id, { modsData: { ...card.modsData, [ctx.modId]: next } });
  revealed = false; activeId = null; notice = good ? 'Scheduled in ' + interval + ' day(s).' : 'Try again in one minute.';
  await paint();
}
await start('Study Studio', async () => {
  const cards = (await ctx.api.data.listCards()).filter(card => tagsOf(card).includes('lab-study'));
  const dueCards = cards.filter(card => (meta(card).due || 0) <= Date.now()).sort((a, b) => (meta(a).due || 0) - (meta(b).due || 0));
  const current = dueCards.find(card => card.id === activeId) || dueCards[0];
  if (current?.id !== activeId) { activeId = current?.id || null; revealed = false; }
  const reviews = cards.reduce((sum, card) => sum + (meta(card).reviews || 0), 0);
  return [
    h('p', {}, cards.length + ' study cards · ' + dueCards.length + ' due · ' + reviews + ' reviews'),
    row([field('Question', front, value => { front = value; }), field('Answer', back, value => { back = value; }, 'textarea'),
      button('Create study card', async () => {
        if (!front.trim() || !back.trim()) throw new Error('Enter both a question and an answer.');
        await ctx.api.data.createCard({ title: front.trim(), body: back.trim(), tags: ['lab-study'] }); front = ''; back = ''; await paint();
      })]),
    current ? box([h('h3', {}, title(current)), revealed ? h('p', { className: 'lab-answer' }, current.body) : h('p', {}, 'Recall the answer before revealing it.'),
      row([button('Reveal answer', async () => { revealed = true; await paint(); }, revealed),
        button('Again', () => grade(current.id, false), !revealed), button('Good', () => grade(current.id, true), !revealed)])]) : h('p', {}, 'All caught up. Refresh when the next card is due.'),
    ...cards.slice(0, 100).map(card => box([h('strong', {}, title(card)), h('small', {}, ' · ' + (meta(card).reviews || 0) + ' reviews · ' +
      (meta(card).due ? 'Next: ' + new Date(meta(card).due).toLocaleString() : 'Ready now')),
      button('Reset schedule', async () => {
        const fresh = await ctx.api.data.getCard(card.id);
        if (!fresh) throw new Error('Card no longer exists.');
        await ctx.api.data.updateCard(card.id, { modsData: { ...fresh.modsData, [ctx.modId]: { schema: 1, due: 0, interval: 0, reviews: 0, lapses: 0 } } });
        revealed = false; await paint();
      })]))
  ];
});
